"""Randomised request generator producing legal (and sometimes illegal) sessions."""
import json, random, sys
sys.path.insert(0, '/workspace/dev')
from ref import Topo, clos_pairs

TOPOS = [
    ['leaf-spine', 3, 1], ['leaf-spine', 4, 2], ['leaf-spine', 6, 2], ['leaf-spine', 2, 1],
    ['clos', 4, 'tor', 0], ['clos', 4, 'pod', 1], ['clos', 6, 'tor', 1], ['clos', 6, 'pod', 0],
    ['clos', 8, 'tor', 1], ['clos', 8, 'pod', 1],
    ['torus2d', 3, 'host'], ['torus2d', 4, 'row'], ['torus2d', 5, 'host'], ['torus2d', 4, 'host'],
    ['torus3d', 3, 'host'], ['torus3d', 4, 'line'], ['torus3d', 3, 'line'],
    ['dragonfly', 4, 3, 1, 'router'], ['dragonfly', 4, 3, 1, 'group'], ['dragonfly', 4, 3, 1, 'target'],
    ['dragonfly', 3, 2, 1, 'group'], ['dragonfly', 6, 5, 1, 'target'],
    ['dragonfly-plus', 4, 2, 3, 1, 0, 'tor'], ['dragonfly-plus', 4, 2, 3, 1, 0, 'group'],
    ['dragonfly-plus', 3, 4, 2, 0, 1, 'group'], ['dragonfly-plus', 2, 2, 1, 1, 0, 'tor'],
    ['dragonfly-plus', 5, 3, 2, 1, 0, 'group'],
]

def build_session(rng, spec, ntasks=None, ngroups=None, ntx=None, neds=None, tight=True,
                  pins=True, force_bad=None):
    topo = Topo(spec)
    n = topo.n
    tcount = len(topo.foots)
    by_dom = {}
    for tid, dom in enumerate(topo.domains):
        by_dom.setdefault(dom, []).append(tid)
    doms = sorted(by_dom)
    g = ngroups or rng.randint(1, min(8, max(1, tcount)))
    groups = []
    gdom = []
    for gid in range(g):
        dom = rng.choice(doms)
        cls = rng.choice([0, 1, 7, 42])
        quota = rng.randint(1, 6)
        budget = rng.choice([1, 3, 10, 10 ** 12])
        groups.append([quota, budget])
        gdom.append((dom, cls))
    d = ntasks or rng.randint(1, 30)
    tasks = []
    for tid in range(d):
        gid = rng.randrange(g)
        dom, cls = gdom[gid]
        tid_tpl = rng.choice(by_dom[dom])
        weight = rng.randint(1, max(1, min(5, groups[gid][0] * groups[gid][1])))
        pin = 1 if (pins and rng.random() < 0.3) else 0
        tasks.append([tid_tpl, gid, weight, cls, pin])
    # derived group footprints
    fp = [set() for _ in range(g)]
    for t in tasks:
        fp[t[1]] |= set(topo.foots[t[0]])
    caps = [0] * n
    for gid in range(g):
        if not fp[gid]:
            continue
        for x in fp[gid]:
            caps[x] += groups[gid][0]
    for x in range(n):
        slack = 0 if (tight and rng.random() < 0.5) else rng.randint(0, 4)
        caps[x] += slack
        if rng.random() < 0.15:
            caps[x] = max(caps[x], rng.randint(0, 3))
    # shrink budgets so proposals can trip the work limit
    for gid in range(g):
        load = sum(t[2] for t in tasks if t[1] == gid)
        q = groups[gid][0]
        if q and load // q == 0:
            groups[gid][1] = max(1, load // q)
    if force_bad == 'mixed':
        if d >= 2 and g >= 1:
            tasks[1][3] = tasks[0][3] + 1
        else:
            return None
    if force_bad == 'quota0':
        idx = next((i for i, t in enumerate(tasks) if True), None)
        gid = tasks[idx][1]
        groups[gid][0] = 0
    if force_bad == 'work':
        idx = max(range(d), key=lambda i: tasks[i][2])
        gid = tasks[idx][1]
        groups[gid][1] = 1
        groups[gid][0] = 1
        tasks[idx][2] = 10 ** 9
    if force_bad == 'capacity':
        for x in range(n):
            if caps[x] > 0:
                caps[x] = 0
                break
        else:
            return None
    queries = lambda: {'groups': [rng.randrange(g) for _ in range(rng.randint(0, 4))],
                       'nodes': [rng.randrange(n) for _ in range(rng.randint(0, 5))],
                       'tasks': [rng.randrange(d) for _ in range(rng.randint(0, 4))] if d else []}
    txs = []
    rev = 0
    for _ in range(ntx or rng.randint(0, 8)):
        stale = rng.random() < 0.12
        r = rev if not stale else max(0, rev + rng.choice([-1, 1, 2, 5]))
        edits = []
        for _ in range(neds if neds is not None else rng.randint(0, 6)):
            kinds = ['move', 'weight', 'class', 'bind', 'pin', 'quota', 'budget', 'cap']
            kind = rng.choice(kinds) if isinstance(kind, str) else kind
            if d == 0 and kind in ('move', 'weight', 'class', 'bind', 'pin'):
                kind = 'quota'
            if kind == 'move':
                edits.append(['move', rng.randrange(d), rng.randrange(g)])
            elif kind == 'weight':
                edits.append(['weight', rng.randrange(d), rng.randint(1, 10 ** 9) if rng.random() < .5 else rng.randint(1, 5)])
            elif kind == 'class':
                edits.append(['class', rng.randrange(d), rng.choice([0, 1, 7, 42, 99])])
            elif kind == 'bind':
                edits.append(['bind', rng.randrange(d), rng.randrange(tcount)])
            elif kind == 'pin':
                edits.append(['pin', rng.randrange(d), rng.randint(0, 1)])
            elif kind == 'quota':
                edits.append(['quota', rng.randrange(g), rng.randint(0, 64)])
            elif kind == 'budget':
                edits.append(['budget', rng.randrange(g), rng.choice([1, 2, 10, 10 ** 12])])
            elif kind == 'cap':
                edits.append(['cap', rng.randrange(n), rng.randint(0, 40)])
        txs.append({'revision': r, 'edits': edits, 'query': queries()})
        if not stale and rng.random() < 0.5:
            pass
    return {'topology': spec, 'caps': caps, 'groups': groups, 'tasks': tasks,
            'query': queries(), 'transactions': txs}

def build_request(seed, sessions=2, force_bad=None, **kw):
    rng = random.Random(seed)
    out = []
    for _ in range(sessions):
        spec = rng.choice(TOPOS)
        s = build_session(rng, spec, force_bad=force_bad, **kw)
        if s is None:
            continue
        out.append(s)
    return {'version': 2, 'sessions': out}

if __name__ == '__main__':
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    print(json.dumps(build_request(seed), separators=(',', ':')))
